import json

def verify_log_file():
    log_file_path = "storage/progressor/raw_eval_logs/all_transgen_logs.jsonl"
    generation_ids = set()
    line_count = 0

    try:
        with open(log_file_path, "r") as f:
            for line in f:
                line_count += 1
                try:
                    data = json.loads(line)
                    if "generation_id" in data:
                        generation_ids.add(data["generation_id"])
                except json.JSONDecodeError:
                    print(f"Error decoding JSON on line {line_count}")

        print("--- Verification Report ---")
        print(f"File: {log_file_path}")
        print(f"Total entries (lines): {line_count}")

        sorted_gens = sorted(list(generation_ids), key=int)
        print(f"Unique generations found: {len(generation_ids)}")
        print(f"Generations: {', '.join(sorted_gens)}")

        if line_count == 10 and len(generation_ids) == 10 and set(map(str, range(1, 11))) == generation_ids:
            print("\nVerification SUCCESS: All 10 unique generations are present.")
        else:
            print("\nVerification FAILED: Mismatch in expected entry count or generations.")

    except FileNotFoundError:
        print(f"Error: Log file not found at {log_file_path}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    verify_log_file()
